  "new_string": "/* ---- Settings Emberstone Studio footer ----
   Deliberately quieter than a real settings section: a muted eyebrow label
   (not a bordered h3) and ghost-style links (not the solid bordered
   .settings-action-btn look) so this credit/support footer reads as
   "links out" rather than "more settings controls" sitting next to it. */

.settings-emberstone {
  margin-top: 20px;
}

.settings-emberstone-label {
  margin-bottom: 8px;
}

.settings-emberstone-links {
  display: flex;
  flex-direction: row;
  gap: 8px;
  width: 100%;
}

.settings-emberstone-icon {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  object-fit: contain;
}

.settings-emberstone-icon.load-failed {
  visibility: hidden;
}

/* Ghost buttons: no border/fill at rest, so they sit visually lighter than
   functional controls like "Refresh all thumbnails" above them. Center an
   icon + label pair since these read as calls to action, not settings rows.
   Visible focus ring for keyboard users. */
.settings-emberstone-link {
  flex: 1 1 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-secondary);
  text-align: center;
  text-decoration: none;
  transition:
    background var(--transition),
    color var(--transition);
}

.settings-emberstone-link:hover {
  background: var(--surface-hover);
  color: var(--text-primary);
}

.settings-emberstone-link:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}"
}

