1	// The single dropdown shell shared by every search-zone popup: the
2	// bookmarks/history scope view, the "search everything" results, and
3	// settings. It owns placement (anchored beneath the search pill), chrome
4	// (surface, radius, shadow via the .search-popup class), open/close state,
5	// and mutual exclusion. Callers own only the content they render into `el`.
6	
7	const registry = new Set();
8	
9	export function createSearchPopup({
10	  anchor,
11	  id,
12	  ariaLabel,
13	  role = "dialog",
14	  onOpenChange,
15	} = {}) {
16	  const openChangeListeners = new Set();
17	  const el = document.createElement("div");
18	  el.className = "search-popup hidden";
19	  if (id) el.id = id;
20	  el.setAttribute("role", role);
21	  if (ariaLabel) el.setAttribute("aria-label", ariaLabel);
22	  (anchor || document.body).appendChild(el);
23	
24	  const api = {
25	    el,
26	    isOpen: () => !el.classList.contains("hidden"),
27	    addOpenChangeListener(listener) {
28	      openChangeListeners.add(listener);
29	      return () => openChangeListeners.delete(listener);
30	    },
31	    open() {
32	      if (api.isOpen()) {
33	        for (const listener of openChangeListeners) listener(true);
34	        return;
35	      }
36	      // Only one dropdown may sit under the pill at a time.
37	      for (const other of registry) {
38	        if (other !== api && other.isOpen()) other.close();
39	      }
40	      el.classList.remove("hidden");
41	      onOpenChange?.(true);
42	      for (const listener of openChangeListeners) listener(true);
43	    },
44	    close() {
45	      if (!api.isOpen()) return;
46	      el.classList.add("hidden");
47	      onOpenChange?.(false);
48	      for (const listener of openChangeListeners) listener(false);
49	    },
50	  };
51	
52	  registry.add(api);
53	  return api;
54	}
